head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.gVar = { "body" : "" };

scwin.hookRequest = function () {
    scwin.gVar.body = "";
    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };
    scwin.gVar.unhook = function () { HTMLFormElement.prototype.submit = fnSubmit; };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다.
scwin.getSentValue = function (sKey) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// subTotalScale 값만 달리하여 advancedExcelDownload 실행
scwin.runCase = function (nScale, strFileName) {
    let options = {
        "fileName" : strFileName,
        "extension" : "xlsx",
        "useSubTotal" : "true",
        "subTotalScale" : nScale,
        "subTotalRoundingMode" : "HALF_UP"
    };

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(options);
    } finally {
        scwin.gVar.unhook();
    }

    scwin.setReturnValue("전달한 subTotalScale : " + nScale + " / subTotalRoundingMode : HALF_UP");
    scwin.setReturnValue("서버로 전달된 subTotalScale : " + scwin.getSentValue("subTotalScale"));
    scwin.setReturnValue("파일명 : " + strFileName + ".xlsx");
}



// subTotalScale 0
scwin.btn_scale0_onclick = function () {
    scwin.runCase(0, "dl_subTotalScale_0");
};
